import{u as i,j as e,c as s,L as n}from"./styles-BBqz0KuQ.js";import{B as c}from"./BookingFlow-DFJyTgbK.js";import{R as t,M as l}from"./ui-D9WAc1mH.js";import"./api-BZpWLNK8.js";const d=[{name:"Trader Pass",price:0,priceHtml:"Register interest <em>— no payment collected now</em>",desc:"2-day exhibition access · booths · demos · networking areas · digital badge"},{name:"Pro Trader Pass",price:0,tag:"Most popular",priceHtml:"Register interest <em>— no payment collected now</em>",desc:"Everything in Trader, plus full conference access · priority seating · fast-track entry"},{name:"VIP Pass",price:0,priceHtml:"Register interest <em>— no payment collected now</em>",desc:"Everything in Pro, plus VIP lounge · reserved seating · exclusive networking"}],h=[["How do I book a ticket for Traders Expo Johannesburg?","Choose your pass — Trader, Pro Trader or VIP — on the tickets page, fill in your name and email, and complete the booking. You will receive a confirmation email with your ticket and a booking reference. You can also re-download your ticket anytime from the ticket holder portal. Registering now collects no payment — pricing will be confirmed with you before anything is charged."],["What is the difference between Trader, Pro Trader and VIP passes?","The Trader pass gives you full access to the exhibition floor, exhibitor booths and networking areas. Pro Trader adds the two-day conference program, panels and workshops. VIP adds everything in Pro Trader plus the premium lounge, front-row seating, exclusive networking sessions and priority entry. Pick the pass that matches how deep you want to go."],["How will I receive my ticket after booking?","After you complete your booking, your ticket is emailed to you automatically with your booking reference and a downloadable ticket. You can also log in to the ticket holder portal anytime to view, re-download or print your ticket. Keep your booking reference handy — you will need it for entry and support."],["Can I transfer my ticket to someone else?","Yes, tickets can be transferred to another person before the event. Contact the support team or use the ticket holder portal to update the attendee name on your booking. The new attendee will need a valid ID matching the updated name at entry. Transfers are free — just make sure the details are correct."],["Are group or corporate ticket discounts available?","Yes. If you are bringing a team, a trading community or a corporate group, group passes are available at preferential rates. Contact the team through the contact page with your group size, and they will arrange a tailored quote. Group bookings also simplify entry — everyone receives their own ticket under one booking."],["What is the refund policy for tickets?","Tickets are generally non-refundable, except where required by law or stated in the official terms. If the event is rescheduled, your ticket remains valid for the new dates; if it is cancelled, refunds will be processed per the official policy. Check the terms on the tickets page before booking, and contact support with questions."],["Can I upgrade my ticket pass later?","Yes, you can upgrade from Trader to Pro Trader or VIP by paying the price difference, subject to availability. Contact the support team with your booking reference and they will arrange the upgrade. Upgrades are easiest before the event — on-site upgrades depend on remaining capacity, so arrange yours in advance."],["Do I need to print my ticket?","No — a digital ticket on your phone is enough for entry. Your ticket email and the ticket holder portal both let you display or download your ticket. Just make sure your phone is charged and your booking reference is accessible. Printed copies are accepted too, if you prefer a backup."]];function p(){const a=i();return e.jsxs("main",{children:[e.jsx("section",{className:"page-hero has-img",style:{"--ph-img":`url('${a}img/profx/profx-16.webp')`},children:e.jsxs("div",{className:"container",children:[e.jsx(t,{className:"eyebrow",children:"Tickets"}),e.jsx(t,{as:"h1",children:"Book your pass."}),e.jsx(t,{className:"section-lead",children:"Register your interest in under a minute. No payment is collected at this stage — pricing will be confirmed before anything is charged."})]})}),e.jsx(l,{}),e.jsx("section",{className:"section",children:e.jsx("div",{className:"container narrow",children:e.jsx(c,{id:"ticketBooking",refPrefix:"TEA",storeKey:"tea_bookings",apiType:"ticket",options:d})})}),e.jsx("section",{className:"section section-alt",children:e.jsxs("div",{className:"container",children:[e.jsxs(t,{className:"lucky-strip",children:[e.jsx("div",{className:"lucky-glow","aria-hidden":"true"}),e.jsxs("div",{children:[e.jsx("strong",{children:"Live trading contest — staged by an Official Guinness World Records™ Holder"}),e.jsx("span",{children:"A live trading contest runs across both expo days. Full contest rules, entry details and prizes will be announced closer to the event."})]})]}),e.jsxs(t,{className:"group-banner",children:[e.jsxs("div",{children:[e.jsx("h3",{children:"Coming with your community or team?"}),e.jsx("p",{children:"Special group packages for trading communities, colleges & universities, corporate teams, financial academies and affiliate networks."})]}),e.jsx("a",{href:"contact.html",className:"btn btn-ghost",children:"Enquire for Group Tickets"})]})]})}),e.jsx("section",{className:"aeo-faq","aria-label":"Frequently asked questions",children:e.jsxs("div",{className:"container",children:[e.jsx("h2",{className:"aeo-faq-title",children:"Frequently Asked Questions"}),h.map(([r,o])=>e.jsxs("details",{className:"aeo-faq-item",children:[e.jsx("summary",{className:"aeo-faq-q",children:r}),e.jsx("p",{className:"aeo-faq-a",children:o})]},r))]})})]})}s(document.getElementById("root")).render(e.jsx(n,{page:"tickets",children:e.jsx(p,{})}));
